// Animated Cardbit Club versions of the Latch & Friends icons (site only). Art is generated by
// scripts/site/make-club-icons.mjs into public/site/img/club/. Unlocked while a Club plan's perks apply.
import { ICONS } from "../../lib/cardbit-levels";
import { PLAN } from "./plan-brand";

export const CLUB_SUFFIX = "-club";
export const isClubIcon = (id: unknown): id is string => typeof id === "string" && id.endsWith(CLUB_SUFFIX) && ICONS.some((i) => i.id + CLUB_SUFFIX === id);
export const clubIconUrl = (id: string) => `/site/img/club/cardbit-icon-${id}`.replace(/-club$/, "") + "-club.svg";
export const CLUB_ICON_URLS: Record<string, string> = Object.fromEntries(ICONS.map((i) => [i.id + CLUB_SUFFIX, clubIconUrl(i.id + CLUB_SUFFIX)]));

/** Icons list entries for the Rewards page picker. */
export const clubIcons = (unlocked: boolean) =>
  ICONS.map((i) => ({ id: i.id + CLUB_SUFFIX, name: `${i.name} ${PLAN.short}`, minLevel: 1, animated: true, subscription: true, club: true, unlocked }));

/** Add the Club icon URLs to a ported page's data-icons map. */
export function withClubIconUrls(html: string) {
  return html.replace(/data-icons='(\{[^']*\})'/g, (_m, json: string) => {
    try {
      return `data-icons='${JSON.stringify({ ...JSON.parse(json), ...CLUB_ICON_URLS })}'`;
    } catch {
      return _m;
    }
  });
}
